const state = {view:'map', target:'MECH-PRAYERS', lens:'全部', focus:true, search:'', detail:'ability', path:0, phase:0, catalog:'powers', item:'', status:'all', zoom:1, fit:true, graphWide:false, deliveryGroup:'requirements', deliveryFeature:'all', deliveryStatus:'all', deliverySearch:'', calc:{planet:1,system:1,cosmic:1,insight:0,wounds:0,population:81,cohesion:80}};
const nav = [['map','机制全景'],['turn','回合时序'],['paths','因果路线'],['catalog','内容图鉴'],['lab','数值试算'],['delivery','实施追踪'],['discussion','讨论簿']];
