const fieldTitles = {id:'内容编号',name:'名称',title:'标题',unlock_awakening:'苏醒门槛',whispers:'低语成本',faith_cost:'信仰成本',check_kind:'检定方式',attribute:'主属性',target_requirement:'对象与条件',deep_success:'深成',success:'成功',failure:'失败',disaster:'灾变',always_cost:'始终代价',cooldown_turns:'冷却回合',notes:'说明',origin:'来源',carry_effect:'携带收益',carry_cost:'使用代价',anchor_role:'锚点用途',faith_disassembly:'转化信仰',insight_disassembly:'转化洞见',follower_gift:'转化信众',whisper_release:'释放低语',release_side_effect:'释放代价',tier:'文明层级',tech:'科技',occult:'秘术',faith:'信仰',meme:'思潮',communication:'传播结构',authority:'权力组织',weakness:'现实矛盾',barrier:'屏障',stability:'稳定',entry_route:'进入方式',spread_route:'传播方式',anchor_route:'扎根方式',resistance_style:'抵抗方式',profile_id:'文明编号',allowed_authority:'允许的组织结构',entry_requirement:'进入条件',spread_requirement:'传播条件',institution_acceptance:'机构承认条件',forbidden_shortcut:'禁止捷径',relic_pool:'圣物类型池',need:'诉求类型',actor_condition:'人物资格',lifetime:'有效回合',shallow_gain:'浅触收益',shallow_cost:'浅触代价',deep_gain:'深干预收益',deep_cost:'深干预代价',fact_tag:'事实标签',callback_event:'后续事件',prayer_id:'祈求编号',success_fact:'成功事实',failure_fact:'失败事实',expiry_fact:'到期事实',cost_semantics:'条件代价',family:'事件族',trigger_fact:'触发事实',min_age:'最早回合',max_age:'最迟回合',cooldown:'冷却',priority:'优先级',scope:'作用对象',invalid_target_policy:'对象失效处理',choice_a:'选项 A',choice_b:'选项 B',default_result:'默认后果',event_id:'事件编号',option:'分支',eligibility:'资格',on_choose:'执行结果',irreversible_cost:'不可逆代价',min_alert:'察觉门槛',required_target:'目标资格',warning_turns:'预告回合',result:'后果',invalid_policy:'目标失效策略',group:'所属系统',value:'初始值',unit:'单位',rationale:'设计理由',status:'状态',will:'意志',insight:'洞察',influence:'影响',adaptation:'适应',sanity:'理智',loyalty:'忠诚',role:'身份',situation:'处境'};
Object.assign(fieldTitles,{need_tags:'处境标签',base_score:'基础倾向',attribute_weight:'属性权重',need_bonus:'处境加成',effect:'状态效果',effect_base:'效果基数',effect_divisor:'属性换算',sanity_cost:'理智代价',target_loyalty_delta:'目标忠诚变化',source_kind:'所需事实',repeat_policy:'重复限制',institution_role:'机构职责',evidence_requirement:'证据条件',target_kind:'目标类别',followers_loss_ratio:'信众损失比例',cohesion_delta:'凝聚变化',barrier_delta:'屏障变化',pollution_delta:'污染变化',wounds_delta:'创伤变化'});
const kindLabels = {question:'问题',change:'修改建议',concern:'设计顾虑'};
const statusLabels = {open:'待讨论',answered:'已回应',planned:'待落实',archived:'已归档'};
const deliveryLabels = {requirements:'关键行为',contracts:'结算约定',tasks:'开发任务',scenarios:'验收场景'};
const trackingLabels = {passed:'当前证据通过',partial:'部分有证据',failed:'验证失败',stale:'证据已过期',unverified:'尚未验证',planned:'待实施','in-progress':'实施中',implemented:'已接入待验收',verified:'任务验收通过',contract:'已登记约定'};
const trackingStatusLabel = value => trackingLabels[value] || value;

function feature(id){return model.features.find(f=>f.id===id);}
function relation(id){return model.relations.find(r=>r.id===id);}
function tracked(id){return deliveryItem(model.delivery,id);}
function targetExists(id){return !!(feature(id)||relation(id)||targetData(id)||tracked(id));}
function name(id){return feature(id)?.title || relation(id)?.label || targetData(id)?.title || tracked(id)?.title || id;}
function key(row){return row.id || (row.option ? `${row.event_id}-${row.option}` : Object.values(row)[0]);}
function targetData(id){
 if(typeof id!=='string'||!id.startsWith('DATA-')) return null;
 const [table, ...rowParts] = id.slice(5).split('/'), rowId=rowParts.join('/'); const t=model.tables[table]; if(!t) return null;
 const row=t.rows.find(r=>key(r)===rowId); if(rowId&&!row)return null; return {table,t,row,title:row?.name||row?.title||rowId||catalogTitles[table]||table};
}
function sourcePaths(id){const f=feature(id),r=relation(id),d=targetData(id),t=tracked(id);return f?.sources.map(s=>s.path)||r?.sources.map(s=>s.path)||(d?[d.t.path]:t?[...(t.sources||[]),...(t.evidence||[]).map(e=>e.report)]:[]);}
function sourcesHTML(paths){return [...new Set(paths)].map(p=>`<button class="source-link" data-action="source" data-path="${esc(p)}">↗ ${esc(p)}</button>`).join('');}
function pill(f){return f?.delivery==='dev'?'<span class="pill evidence">局部技术证据</span>':'<span class="pill proposed">设计提案</span>';}
function fieldLabel(k,table){return k==='faith'&&table==='powers'?'信仰成本':fieldTitles[k]||k;}
function displayField(k,v){const vocabulary={attribute:{will:'意志',insight:'洞察',influence:'影响',adaptation:'适应',none:'无需属性'},check_kind:{social:'社会检定',occult:'异质检定',none:'无随机检定'},tier:{planet:'星球',system:'星系',cosmic:'宇宙'},status:{PROPOSED:'设计提案'}};const translated=vocabulary[k]?.[v];return translated?`${translated}（${v}）`:v;}
function nodeButton(id,label){return `<button data-action="target" data-id="${esc(id)}">${esc(label||name(id))} ↗</button>`;}
function notice(text){return `<div class="notice">${esc(text)}</div>`;}
function toast(message){$('#toast').textContent=message;$('#toast').classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').classList.remove('show'),4800);}
async function request(url,options){const r=await fetch(url,options);const data=await r.json();if(!r.ok) throw new Error(data.error||'读取失败');return data;}
function draft(){return drafts[state.target]||{title:'',body:'',kind:'question'};}
function persistDraft(){try{localStorage.setItem('cthulhu-workbench-drafts-v1',JSON.stringify(drafts));}catch{toast('草稿暂存不可用；当前输入仍在页面，请先复制。');}}
function hashWrite(){const p=new URLSearchParams({view:state.view});if(state.target)p.set('target',state.target);if(state.view==='catalog'){p.set('catalog',state.catalog);if(state.item)p.set('item',state.item);}if(state.view==='paths')p.set('path',String(state.path));if(state.view==='delivery'){p.set('group',state.deliveryGroup);if(state.deliveryFeature!=='all')p.set('feature',state.deliveryFeature);if(state.deliveryStatus!=='all')p.set('status',state.deliveryStatus);if(state.deliverySearch)p.set('q',state.deliverySearch);}history.replaceState(null,'','#'+p.toString());}
function hashRead(){const p=new URLSearchParams(location.hash.slice(1));if(titles[p.get('view')])state.view=p.get('view');const t=p.get('target');if(t&&targetExists(t))state.target=t;if(deliveryGroups.includes(p.get('group')))state.deliveryGroup=p.get('group');else if(tracked(t))state.deliveryGroup=tracked(t).group;state.deliveryFeature=feature(p.get('feature'))?p.get('feature'):'all';state.deliveryStatus=p.get('status')||'all';state.deliverySearch=p.get('q')||'';if(model.tables[p.get('catalog')])state.catalog=p.get('catalog');state.item=p.get('item')||'';state.path=Math.max(0,Math.min(model.paths.length-1,Number(p.get('path'))||0));}
function select(id,view){state.target=id;state.detail='ability';state.search='';if(view)state.view=view;const trace=tracked(id);if(trace){state.view='delivery';state.deliveryGroup=trace.group;}state.graphWide=false;hashWrite();render();if(matchMedia('(max-width:1100px)').matches)$('#inspector').scrollIntoView({block:'start'});}
function metric(count){return ({map:[model.features.filter(f=>f.producer.graph).length,'核心机制'],turn:[model.phases.length,'回合阶段'],paths:[model.paths.length,'阅读路线'],catalog:[Object.keys(model.tables).length,'内容类别'],lab:[2,'公式试算'],delivery:[model.delivery?.requirements?.length||0,'关键行为'],discussion:[count,'条在议事项']})[state.view];}
function render(){
 const count=feedback.items.filter(i=>i.status!=='archived').length;
 const stale=model.meta.changed.length+model.meta.unowned.length;const [metricValue,metricLabel]=metric(count);
 $('#app').innerHTML=`<div class="shell"><aside class="sidebar"><div class="brand"><i class="sigil" aria-hidden="true"></i><h2>邪神苏醒</h2><p>制作工作台</p></div><nav class="nav" aria-label="主要视图">${nav.map(([id,label],i)=>`<button class="${state.view===id?'active':''}" data-action="view" data-view="${id}" title="${label}" aria-current="${state.view===id?'page':'false'}"><span class="navnum">0${i+1}</span><span class="label">${label}${id==='discussion'&&count?` · ${count}`:''}</span></button>`).join('')}</nav><div class="sidebar-line">制作与交付</div><div class="sidebar-extra">${model.features.filter(f=>!f.producer.graph).map(f=>`<button data-action="target" data-id="${f.id}">${esc(f.title)}</button>`).join('')}<button data-action="constraints">已确认的方向 ↗</button></div><div class="sidebar-foot"><strong>一个神迹，一段历史。</strong><br>策划与制作人视角<br>原始规则始终留在项目中。</div></aside><div class="workspace"><header class="topbar"><div class="breadcrumb">制作工作台 <span style="margin:0 9px">/</span> <b>${titles[state.view]}</b></div><div class="top-actions">${offline?`<button class="portable-badge" data-action="provenance">离线快照 · ${new Date(model.meta.loadedAt).toLocaleDateString('zh-CN')}</button>`:`<button class="source-status ${stale?'stale':''}" data-action="provenance"><i class="dot"></i>${stale?`${stale} 处来源待复核`:'项目来源已核对'} · <span class="mono">${model.meta.revision.slice(0,7)}</span></button>`}<button data-action="refresh">更新来源</button><button data-action="export-notes">导出讨论</button></div></header><div class="pagehead"><div><span class="eyebrow">DESIGN ATLAS / ${state.view.toUpperCase()}</span><h1>${titles[state.view]}</h1><p>${({map:'看见每个机制的能力，也看见它付给其他系统的代价。',turn:'把结算顺序展开，理解哪些后果立即发生、哪些留到轮末。',paths:'沿一条具体关系链，理解神意怎样进入世界，再回到你身上。',catalog:'直接读取策划数据，定位一项权能、一种文明或一个后果。',lab:'调整假设，观察当前公式的结果。不会修改策划数据，也不是游戏模拟。',delivery:'从一项关键行为追到结算约定、开发任务与验收证据，清楚看见仍未落实的部分。',discussion:'把问题留在具体机制和关系上，让下一轮协作从同一个上下文开始。'})[state.view]}</p></div><div class="countbox"><b>${metricValue}</b>${metricLabel}<br><span>${state.view==='delivery'?'覆盖、接入、验收分别记录':'规则提案 · 正式游戏尚未完成'}</span></div></div>${stale?`<div class="stale-banner"><b>来源发生变化，能力摘要需复核。</b> ${esc([...model.meta.changed,...model.meta.unowned].slice(0,3).join(' · '))}。数值与原文已重新读取，索引摘要不会被自动当作已同步。</div>`:''}<div class="body-area ${state.view==='map'&&state.graphWide?'wide-map':''}"><main class="main" id="main-view">${mainHTML()}</main><aside class="inspector" aria-label="机制详情" id="inspector">${inspectorHTML()}</aside></div></div></div>`;
 if(state.view==='map'){if(state.fit){state.zoom=Math.min(1,$('.graph-viewport').clientWidth/1120);$('#graph-scale').style.width=state.zoom*1120+'px';}bindGraphPan();}
 if(state.view==='lab') updateCalculation();
}
function mainHTML(){return ({map:mapHTML,turn:turnHTML,paths:pathsHTML,catalog:catalogHTML,lab:labHTML,delivery:deliveryHTML,discussion:discussionHTML})[state.view]();}
function mapHTML(){
 const query=state.search.trim().toLowerCase(), selected=feature(state.target), chosen=relation(state.target);
 const relevant = r => (state.lens==='全部'||r.kind===state.lens)&&(!state.focus||!selected&&!chosen||(chosen?r.id===chosen.id:r.from===selected.id||r.to===selected.id));
 const activeEdges=model.relations.filter(relevant);
 const neighbor=new Set(activeEdges.flatMap(r=>[r.from,r.to]));if(selected)neighbor.add(selected.id);
 const point=id=>{const p=feature(id).producer;return {x:40+260*p.column,y:102+147*p.row};};
 let svg=`<svg viewBox="0 0 1120 720" aria-label="游戏机制关系图"><defs><pattern id="dots" width="18" height="18" patternUnits="userSpaceOnUse"><circle cx="1" cy="1" r=".7" fill="#dbe5dc"/></pattern><marker id="arrow" viewBox="0 0 10 10" refX="9" refY="5" markerWidth="6" markerHeight="6" orient="auto-start-reverse"><path d="M 0 0 L 10 5 L 0 10 z" fill="#6c9d89"/></marker><marker id="riskArrow" viewBox="0 0 10 10" refX="9" refY="5" markerWidth="6" markerHeight="6" orient="auto-start-reverse"><path d="M 0 0 L 10 5 L 0 10 z" fill="#b6644e"/></marker></defs><rect width="1120" height="720" fill="url(#dots)"/>`;
 ['神意介入','代理与供给','文明与立足','回响与终点'].forEach((v,i)=>{svg+=`<text class="lane-label" x="${42+260*i}" y="40">0${i+1} / ${v}</text><text class="lane-sub" x="${42+260*i}" y="62">${['你能够做什么','借助谁，付出什么','世界怎样接纳异质','后果如何回到玩家'][i]}</text>`;});
 activeEdges.forEach(r=>{const a=point(r.from),b=point(r.to),same=a.x===b.x,forward=b.x>a.x;let d,mx,my;if(same){const x=a.x+220,y=a.y+45,ey=b.y+45;d=`M${x},${y} C${x+46},${y} ${x+46},${ey} ${x},${ey}`;mx=x+24;my=(y+ey)/2;}else{const x=forward?a.x+220:a.x,y=a.y+45,ex=forward?b.x:b.x+220,ey=b.y+45,m=(x+ex)/2;d=`M${x},${y} C${m},${y} ${m},${ey} ${ex},${ey}`;mx=m;my=(y+ey)/2;}const hi=!!selected||!!chosen;svg+=`<path class="edge ${hi?'highlight':''} ${r.kind==='风险'?'risk':''}" d="${d}" marker-end="url(#${r.kind==='风险'&&hi?'riskArrow':'arrow'})"/><path class="edge-hit" d="${d}" data-action="edge" data-id="${r.id}" tabindex="0" role="button" aria-label="${esc(name(r.from)+' → '+name(r.to)+'：'+r.label)}"><title>${esc(r.label+'：'+r.summary)}</title></path>${hi&&activeEdges.length<8?`<text class="edge-label" x="${mx}" y="${my-7}" text-anchor="middle">${esc(r.label)}</text>`:''}`;});
 model.features.filter(f=>f.producer.graph).forEach((f,i)=>{const p=point(f.id),match=!query||[f.id,f.title,f.summary,...f.producer.capabilities].join(' ').toLowerCase().includes(query),dim=!match||(state.focus&&(selected||chosen)&&!neighbor.has(f.id));svg+=`<g class="node ${f.id===state.target?'selected':''} ${dim?'dim':''}" transform="translate(${p.x},${p.y})" data-action="target" data-id="${f.id}" tabindex="0" role="button" aria-label="${esc(f.title)}"><rect width="220" height="91" rx="7"/><text class="node-id" x="16" y="22">${f.id.replace('MECH-','')}</text><text class="node-title" x="16" y="50">${esc(f.title)}</text><text class="node-sub" x="16" y="73">${esc(f.producer.promise)}</text></g>`;});
 svg+='</svg>';
 return `<div class="toolbar"><div class="filters" aria-label="关系类型">${['全部','资源','条件','风险','因果','时序'].map(k=>`<button data-action="lens" data-value="${k}" class="${state.lens===k?'active':''}">${k}</button>`).join('')}</div><label><span class="sr-only">搜索机制</span><input class="searchbox" id="mechanism-search" type="search" placeholder="搜索机制、能力或编号…" value="${esc(state.search)}"></label></div><div class="graph-shell"><div class="graph-caption"><span>${selected?`正在聚焦：<b>${esc(selected.title)}</b>`:chosen?`关系：${esc(chosen.id)}`:'全景 · 点击节点看能力，点击连线看作用'} · ${activeEdges.length} 条关系</span><div class="row"><button class="small" data-action="wide-map">${state.graphWide?'显示详情':'展开图面'}</button><button class="small" data-action="focus">${state.focus?'显示全关系':'只看相邻关系'}</button><button class="small" data-action="zoom" data-value="-1" aria-label="缩小关系图">−</button><button class="small" data-action="zoom" data-value="1" aria-label="放大关系图">＋</button><button class="small" data-action="fit-map">适应窗口</button><button class="small" data-action="reset-map">复位</button></div></div><div class="graph-viewport"><div id="graph-scale" style="width:${state.zoom*1120}px">${svg}</div></div><div class="graph-legend"><span><i></i>资源 / 条件 / 因果</span><span><i class="risk"></i>风险与反作用</span><span>箭头表示作用方向 · 拖动空白平移</span></div></div><div class="footer-hint">这是策划关系图。节点表示玩家能力、世界机制与体验职责，不表示程序模块。</div>`;
}
function trackingPill(status){const style=['passed','verified'].includes(status)?'green':status==='failed'?'danger':['stale','partial'].includes(status)?'warning':'';return `<span class="pill ${style}">${esc(trackingStatusLabel(status))}</span>`;}
function textList(values){return values?.length?`<ul class="tracking-list">${values.map(v=>`<li>${esc(v)}</li>`).join('')}</ul>`:'<p class="tiny muted">尚未登记。</p>';}
function trackingLinks(ids){return ids?.length?`<div class="tracking-links">${deliveryLinkTargets(model.delivery,ids).map(({id,available})=>available?nodeButton(id):`<span class="tiny muted">${esc(id)} · ${id.startsWith('ISSUE-')?'未决事项，见上方登记':'未登记可定位对象'}</span>`).join('')}</div>`:'<p class="tiny muted">尚未登记关联。</p>';}
function coverageHTML(item){const c=item.coverage||{};return `<div class="coverage-stages"><span class="recorded">规则已登记</span><span class="${c.assigned?'recorded':'gap'}">${c.assigned?'任务已分配':'缺开发任务'}</span><span class="${c.implemented?'recorded':'gap'}">${c.implemented?'已有实现接入':'尚未完整接入'}</span><span class="${c.verification==='passed'?'recorded':'gap'}">${esc(trackingStatusLabel(c.verification||'unverified'))}</span></div>`;}
function trackingCard(item){
 const label=deliveryStatus(item), selected=state.target===item.id;
 const summary=item.rule||item.scope||item.phase||item.when||'';
 const tail=item.group==='requirements'?coverageHTML(item):item.group==='tasks'?`<p class="tiny muted">批次 ${esc(item.stage)} · ${esc(item.owner)} · ${item.readiness?.ready?'前置任务已满足':`等待 ${item.readiness?.blockedBy?.length||0} 项前置`}</p>`:item.group==='contracts'?`<p class="tiny muted">责任：${esc(item.owner)} · ${(item.acceptance||[]).length} 项验收</p>`:`<p class="tiny muted">${item.kind==='manual'?'人工评审':'自动检查'} · ${(item.evidence||[]).length} 条证据引用</p>`;
 return `<article class="tracking-card ${selected?'active':''}"><button class="tracking-card-open" data-action="target" data-id="${esc(item.id)}"><div class="row spread wrap"><span class="mono tiny">${esc(item.id)}</span>${trackingPill(label)}</div><h3>${esc(item.title)}</h3><p>${esc(summary)}</p><span class="tiny tracking-open-label">展开${deliveryLabels[item.group]}与关联 →</span></button>${tail}</article>`;
}
function residualsHTML(){
 const overview=residualOverview(model.delivery?.residuals);
 const intro='<p class="tracking-caption">仅统计没有后续承接计划、需要制作人决策或实际阻塞的事项。正常计划中的任务和未验收场景不计入。</p>';
 if(!overview.valid)return `<section class="residual-section" aria-labelledby="residual-heading"><h3 id="residual-heading">真正未决事项</h3>${intro}<div class="tracking-alert"><strong>统计不可判定</strong>${textList(overview.errors)}<p class="tiny">读取或校验失败不等于没有未决事项。</p></div></section>`;
 const labels={unplanned:'无相关规划',decision:'需制作人决策',blocking:'阻塞事项'};
 const counts=[['open','待处理总数'],['unplanned','无相关规划'],['decision','需制作人决策'],['blocking','存在阻塞']];
 const cards=overview.items.map(item=>`<details class="report-card"><summary><span class="mono tiny">${esc(item.id)}</span> · ${esc(item.title)} <span class="pill ${item.status==='open'?'warning':''}">${item.status==='open'?'待处理':'已关闭'}</span></summary><div class="report-body"><p class="tiny muted">${esc(labels[item.category])} · 负责人：${esc(item.owner)}</p>${trackingSection('问题与影响',`<p class="tiny">${esc(item.description)}</p>`)}${trackingSection('下一步 / 待决策内容',`<p class="tiny">${esc(item.nextAction)}</p>`)}${trackingSection('来源任务',trackingLinks([item.originTask]))}${item.blockedTasks.length?trackingSection('被阻塞任务',trackingLinks(item.blockedTasks)):''}${item.status==='resolved'?trackingSection('关闭记录',`<p class="tiny">${esc(typeof item.resolution==='string'?item.resolution:JSON.stringify(item.resolution||'尚未登记'))}</p>`):''}${trackingSection('记录依据',sourcesHTML(item.sources))}</div></details>`).join('');
 return `<section class="residual-section" aria-labelledby="residual-heading"><h3 id="residual-heading">真正未决事项</h3>${intro}<div class="tracking-overview">${counts.map(([key,label])=>`<div><strong>${overview.summary[key]}</strong><span>${label}</span></div>`).join('')}</div><p class="tracking-caption">阻塞统计也包含其他类别中阻塞任务的事项，以上数字不相加。${overview.summary.open===0?'当前已登记待处理项为 0；':''}统计仅覆盖已登记内容，任务收尾审查不能保证自然语言遗漏已被穷尽。</p>${cards||'<p class="tiny muted">当前没有登记未决事项；后续发现后须在 task 收尾前记录。</p>'}</section>`;
}
function deliveryHTML(){
 const delivery=model.delivery||{},group=state.deliveryGroup;
 const items=filterDelivery(delivery,{group,feature:state.deliveryFeature,status:state.deliveryStatus,query:state.deliverySearch});
 const requirements=delivery.requirements||[],scenarios=delivery.scenarios||[];
 const assigned=requirements.filter(r=>r.coverage?.assigned).length,connected=requirements.filter(r=>r.coverage?.implemented).length;
 const statuses=group==='tasks'?['all','gaps','planned','in-progress','implemented','verified','stale','failed','unverified']:group==='contracts'?['all']:['all','gaps','unverified','partial','stale','failed','passed'];
 const messages=[...(delivery.errors||[]).map(x=>`追踪错误：${x}`),...(delivery.warnings||[])];
 return `<div class="view-content delivery-view"><div class="tracking-overview"><div><strong>${requirements.length}</strong><span>已登记关键行为</span></div><div><strong>${assigned}</strong><span>有开发任务</span></div><div><strong>${connected}</strong><span>已有完整接入</span></div><div><strong>${scenarios.filter(x=>x.verification?.status==='passed').length}<small> / ${scenarios.length}</small></strong><span>当前证据通过的场景</span></div></div><p class="tracking-caption">以上分别表示规则覆盖、任务分配、实现接入和验收事实，不是游戏完成百分比。证据按来源指纹复核，讨论状态不改变这些结果。</p>${messages.length?`<div class="tracking-alert">${textList(messages)}</div>`:''}${residualsHTML()}<div class="path-switch tracking-tabs" aria-label="追踪类别">${deliveryGroups.map(id=>`<button data-action="delivery-group" data-value="${id}" class="${group===id?'active':''}" aria-pressed="${group===id}">${deliveryLabels[id]} <span class="mono">${delivery[id]?.length||0}</span></button>`).join('')}</div><div class="tracking-filters"><label for="delivery-feature-filter">相关机制<select id="delivery-feature-filter" aria-label="相关机制"><option value="all">全部机制</option>${model.features.map(f=>`<option value="${esc(f.id)}" ${state.deliveryFeature===f.id?'selected':''}>${esc(f.title)}</option>`).join('')}</select></label><label for="delivery-status-filter">状态<select id="delivery-status-filter" aria-label="状态">${statuses.map(id=>`<option value="${id}" ${state.deliveryStatus===id?'selected':''}>${id==='all'?'全部状态':id==='gaps'?'尚有缺口':esc(trackingStatusLabel(id))}</option>`).join('')}</select></label><label class="tracking-search" for="delivery-search">查找<input id="delivery-search" aria-label="查找" type="search" placeholder="标题、规则、任务或编号…" value="${esc(state.deliverySearch)}"></label></div><div class="row spread tracking-results"><span class="tiny muted">${items.length} 项${state.deliveryFeature==='all'?'':' · '+esc(name(state.deliveryFeature))}</span><button class="small ghost" data-action="delivery-reset">清除筛选</button></div><div class="tracking-cards">${items.map(trackingCard).join('')||'<div class="empty-search">当前筛选下没有记录。空白不表示已实现；可清除筛选或检查追踪来源。</div>'}</div>${group==='scenarios'?reportsHTML():''}<p class="discussion-help">阅读顺序：关键行为 → 结算约定与开发任务 → 验收场景 → 真实报告。点击任一项可记录讨论，或复制带来源版本的上下文。</p></div>`;
}
function featureDeliveryHTML(id){
 const d=model.delivery||{},req=(d.requirements||[]).filter(x=>x.features.includes(id)),contracts=(d.contracts||[]).filter(x=>x.features.includes(id)),scenarios=(d.scenarios||[]).filter(x=>x.features.includes(id));
 if(!req.length&&!contracts.length&&!scenarios.length)return `<div class="inspect-section"><div class="section-label">实施追踪</div><p class="tiny muted">本机制尚未登记关键行为与验收，不表示已经完成。</p></div>`;
 const unverified=scenarios.filter(x=>x.verification?.status!=='passed');
 return `<div class="inspect-section"><div class="section-label">实施追踪 · ${req.length} 项关键行为</div><p class="tiny muted">${contracts.length} 项结算约定 · ${unverified.length} / ${scenarios.length} 项验收尚无当前通过证据</p>${trackingLinks(req.slice(0,3).map(x=>x.id))}${contracts.length?`<div class="section-label tracking-subtitle">跨系统结算</div>${trackingLinks(contracts.slice(0,2).map(x=>x.id))}`:''}<button class="small" data-action="delivery-feature" data-id="${esc(id)}">查看本机制的全部实施追踪 →</button></div>`;
}
function trackingSection(title,content){return `<section class="inspect-section"><div class="section-label">${esc(title)}</div>${content}</section>`;}
function deliveryInspectorHTML(item){
 const notes=feedback.items.filter(n=>n.target===item.id&&n.status!=='archived'),status=deliveryStatus(item);
 let content='';
 if(state.detail==='notes')content=noteFormHTML()+notes.map(noteHTML).join('');
 else if(state.detail==='relations'){
  content=trackingSection('受影响机制',trackingLinks(item.features))+trackingSection('追踪链的前后关联',trackingLinks(deliveryConnections(model.delivery,item)));
  if(item.relations?.length)content+=trackingSection('策划作用关系',trackingLinks(item.relations));
  if(item.decisions?.length)content+=trackingSection('有效制作约束',textList(item.decisions.map(id=>model.atlas.constraints.find(c=>c.id===id)?.statement||id)));
  if(item.group==='tasks')content+=trackingSection('依赖本任务的后续工作',trackingLinks((model.delivery.tasks||[]).filter(t=>t.dependsOn.includes(item.id)).map(t=>t.id)));
 }else if(item.group==='requirements'){
  content=coverageHTML(item)+trackingSection('必须兑现的规则',`<p class="tiny">${esc(item.rule)}</p>`)+trackingSection('尚缺什么',item.coverage?.missing?.length?textList(item.coverage.missing):'<p class="tiny muted">已登记链路中未发现缺口；验收范围见各场景，不推定未登记行为已覆盖。</p>')+trackingSection('开发任务',trackingLinks(item.tasks))+trackingSection('跨系统结算约定',trackingLinks(item.contracts))+trackingSection('可否证验收',trackingLinks(item.acceptance));
 }else if(item.group==='contracts'){
  content=trackingSection('结算责任与时点',`<p class="tiny"><b>${esc(item.owner)}</b><br>${esc(item.phase)}</p>`)+trackingSection('读取什么',textList(item.reads))+trackingSection('统一写入什么',textList(item.writes))+trackingSection('成立前提',textList(item.preconditions))+trackingSection('同轮冲突与生效顺序',textList(item.resolution))+trackingSection('必须保持的条件',textList(item.invariants))+trackingSection('验证这些约定',trackingLinks(item.acceptance));
 }else if(item.group==='tasks'){
  content=trackingSection('登记进展与当前证据',`<p class="tiny">任务登记：${esc(trackingStatusLabel(item.status))}<br>当前验收：${esc(trackingStatusLabel(item.verification||'unverified'))}</p>`)+trackingSection('本次交付范围',`<p class="tiny">${esc(item.scope)}</p>`)+trackingSection('前置工作',trackingLinks(item.dependsOn))+trackingSection('开工条件',item.readiness?.ready?'<p class="tiny">已登记的前置工作已满足。仍需读取当前规则、影响范围与未决项。</p>':`<p class="tiny">前置任务尚未满足：</p>${trackingLinks(item.readiness?.blockedBy)}`)+trackingSection('交付物',textList(item.deliverables))+trackingSection('验收场景',trackingLinks(item.acceptance))+trackingSection('风险与待关注项',textList(item.risks))+trackingSection('本任务范围以外',textList(item.outOfScope));
 }else{
  content=trackingSection('给定局势',`<p class="tiny">${esc(item.given)}</p>`)+trackingSection('执行什么',`<p class="tiny">${esc(item.when)}</p>`)+trackingSection('必须观察到什么',textList(item.then))+trackingSection('实际验收证据',scenarioEvidenceHTML(item));
 }
 return `<button class="back-overview small" data-action="back-main">↑ 返回实施追踪</button><div class="inspect-head"><div class="row spread"><span class="mono">${esc(item.id)}</span><button class="ghost small" data-action="copy-link" title="复制定位链接">↗ 定位</button></div><h2>${esc(item.title)}</h2>${trackingPill(status)}<p>${deliveryLabels[item.group]} · ${item.group==='tasks'?`批次 ${esc(item.stage)} · ${esc(item.owner)}`:'规则、接入与验收分别追踪'}</p><div class="row"><button class="primary small" data-action="detail" data-value="notes">在此讨论</button><button class="small" data-action="copy-context">复制上下文</button></div></div><div class="section-tabs">${[['ability',item.group==='contracts'?'结算约定':item.group==='scenarios'?'场景与证据':'实施内容'],['relations','影响与关联'],['notes',`讨论${notes.length?' · '+notes.length:''}`]].map(([id,label])=>`<button data-action="detail" data-value="${id}" class="${state.detail===id?'active':''}">${label}</button>`).join('')}</div>${content}${trackingSection('权威来源',sourcesHTML(sourcePaths(item.id)))}`;
}
function scenarioEvidenceHTML(item){
 const evidence=item.verification?.evidence||[];
 if(!evidence.length)return notice(item.kind==='manual'?'尚未记录人工验收证据。设计描述与自动测试不能代替该判断。':'尚未记录可用运行证据。场景已定义不表示已经通过。');
 return evidence.map(e=>`<div class="tracking-evidence"><div class="row spread wrap"><span class="mono tiny">${esc(e.check)}</span>${trackingPill(e.status)}</div><p class="tiny muted">${e.generatedAt?'运行记录：'+esc(new Date(e.generatedAt).toLocaleString('zh-CN')):'尚无有效运行时间'}</p>${sourcesHTML([e.report])}${e.changed?.length?`<p class="tiny">证据之后已变化：</p>${textList(e.changed)}`:''}${e.reason?`<p class="tiny">${esc(e.reason)}</p>`:''}</div>`).join('');
}
function metricValueHTML(value,depth=0){
 if(value===null||typeof value!=='object')return esc(value);
 if(depth>3)return esc(JSON.stringify(value));
 if(Array.isArray(value))return `<ul class="tracking-list">${value.map(v=>`<li>${metricValueHTML(v,depth+1)}</li>`).join('')}</ul>`;
 return `<dl class="report-metrics">${Object.entries(value).map(([key,v])=>`<div><dt>${esc(key)}</dt><dd>${metricValueHTML(v,depth+1)}</dd></div>`).join('')}</dl>`;
}
function reportsHTML(){
 const reports=model.delivery?.reports||[];
 if(!reports.length)return '';
 return `<section class="tracking-reports"><h3>验收报告与适用范围</h3><p class="tiny muted">指标属于报告声明的运行条件，不能据此推定完整游戏或其他机器通过。</p>${reports.map(r=>`<details class="report-card"><summary><span>${esc(r.title||r.path)}</span><span class="pill ${r.current?'':'warning'}">${r.current?'来源指纹匹配':'来源已变或待核对'}</span></summary><div class="report-body"><p class="tiny muted">${r.generatedAt?esc(new Date(r.generatedAt).toLocaleString('zh-CN')):'运行时间未登记'}</p>${sourcesHTML([r.path])}${r.changed?.length?trackingSection('来源已变化',textList(r.changed)):''}${r.scope?trackingSection('验证范围',Array.isArray(r.scope)?textList(r.scope):`<p class="tiny">${esc(r.scope)}</p>`):''}${r.metrics?trackingSection('实测记录',metricValueHTML(r.metrics)):''}${r.limitations?trackingSection('不在证据范围内',Array.isArray(r.limitations)?textList(r.limitations):`<p class="tiny">${esc(r.limitations)}</p>`):''}</div></details>`).join('')}</section>`;
}

function inspectorHTML(){
 const implementation=tracked(state.target);if(implementation)return deliveryInspectorHTML(implementation);
 if(!state.target)return `<div class="empty-detail"><span class="eyebrow">FOLLOW THE CONSEQUENCE</span><h2>从一个机制，<br>看见整个世界。</h2><p>选择节点看能力与代价，选择连线理解作用。用稳定编号，把讨论落在同一处设计上。</p>${model.paths.map((p,i)=>`<button class="mini-path" data-action="path" data-value="${i}"><span>${esc(p.subtitle)}</span>${esc(p.title)} →</button>`).join('')}</div>`;
 const f=feature(state.target),r=relation(state.target),data=targetData(state.target),notes=feedback.items.filter(i=>i.target===state.target&&i.status!=='archived');
 if(!f&&!r&&!data)return '';
 const title=name(state.target), summary=f?.summary||r?.summary||'当前策划表中的原始定义。';
 const tabs=`<div class="section-tabs">${[['ability',data?'定义':r?'作用':'能力'],['relations','关联'],['notes',`讨论${notes.length?' · '+notes.length:''}`]].map(([id,label])=>`<button data-action="detail" data-value="${id}" class="${state.detail===id?'active':''}">${label}</button>`).join('')}</div>`;
 let content='';
 if(state.detail==='notes') content=noteFormHTML()+notes.map(noteHTML).join('');
 else if(state.detail==='relations'){
  if(f){const incoming=model.relations.filter(x=>x.to===f.id),outgoing=model.relations.filter(x=>x.from===f.id);content=`<div class="section-label">什么影响它 · ${incoming.length}</div>${incoming.map(x=>relItem(x,true)).join('')||'<p class="tiny muted">当前没有登记直接输入关系。</p>'}<div class="inspect-section"><div class="section-label">它会影响什么 · ${outgoing.length}</div>${outgoing.map(x=>relItem(x,false)).join('')||'<p class="tiny muted">当前没有登记直接输出关系。</p>'}</div>`;}
  else if(r)content=`<div class="stack">${nodeButton(r.from,'起点 · '+name(r.from))}${nodeButton(r.to,'终点 · '+name(r.to))}</div><div class="inspect-section">${notice('连线描述策划关系，不是自动推导出的程序依赖或必然发生的模拟结果。')}</div>`;
  else content=`<div class="section-label">相关机制</div><div class="chips">${model.features.filter(x=>x.sources.some(s=>s.path===data.t.path)).map(x=>nodeButton(x.id)).join('')}</div>`;
 }else if(f){const p=f.producer;content=`<div class="section-label">玩家 / 系统能够做什么</div>${p.capabilities.map(c=>`<div class="capability">${esc(c)}</div>`).join('')}${p.inputs.length||p.outputs.length?`<div class="io"><div><span>需要什么</span>${p.inputs.map(esc).join('<br>')}</div><div><span>改变什么</span>${p.outputs.map(esc).join('<br>')}</div></div>`:''}<div class="tradeoff">${esc(p.tradeoff)}</div><div class="inspect-section"><div class="section-label">不能被改丢的边界</div><ul>${p.guardrails.map(x=>`<li>${esc(x)}</li>`).join('')}</ul></div><div class="inspect-section"><div class="section-label">制作人应留意</div><p class="tiny">${esc(p.question)}</p></div><div class="inspect-section"><div class="section-label">状态与证据边界</div><p class="tiny muted">${f.delivery==='dev'?'局部能力已有技术证据；具体接入与验收范围见实施追踪。':'规则已成提案；实现、平衡与体验仍待验证。'}</p></div>`;
 }else if(r)content=`<div class="row" style="margin-bottom:20px;flex-wrap:wrap">${nodeButton(r.from)}<span>→</span>${nodeButton(r.to)}</div><div class="section-label">关系类型</div><span class="pill">${esc(r.kind)}</span><div class="inspect-section"><div class="tradeoff">${esc(r.summary)}</div></div><div class="inspect-section"><p class="tiny muted">提出修改时，既要看起点的收益，也要看终点因此失去的约束。</p></div>`;
 else if(data.row)content=`<dl>${Object.entries(data.row).map(([k,v])=>`<div class="data-field"><dt>${esc(fieldLabel(k,data.table))}</dt><dd>${esc(displayField(k,v))}</dd></div>`).join('')}</dl>`;
 else content=`<p class="tiny">${data.t.rows.length} 条定义，读取自项目 CSV。</p>`;
 return `<button class="back-overview small" data-action="back-main">↑ 返回当前视图</button><div class="inspect-head"><div class="row spread"><span class="mono">${esc(state.target)}</span><button class="ghost small" data-action="copy-link" title="复制定位链接">↗ 定位</button></div><h2>${esc(title)}</h2>${pill(f)}<p>${esc(summary)}</p><div class="row"><button class="primary small" data-action="detail" data-value="notes">在此讨论</button><button class="small" data-action="copy-context">复制上下文</button></div></div>${tabs}${content}${f?featureDeliveryHTML(f.id):''}<div class="inspect-section"><div class="section-label">权威来源</div>${sourcesHTML(sourcePaths(state.target))}</div>`;
}
function relItem(r,incoming){return `<button class="relation-item" data-action="edge" data-id="${r.id}"><span class="arrow">${incoming?'↙':'↗'}</span><span>${esc(r.label)}<small>${esc(name(incoming?r.from:r.to))} · ${esc(r.id)}</small></span></button>`;}
function noteFormHTML(){const d=draft();return `<form class="note-form" id="note-form"><label>讨论类型<select id="note-kind">${Object.entries(kindLabels).map(([v,t])=>`<option value="${v}" ${d.kind===v?'selected':''}>${t}</option>`).join('')}</select></label><label>议题标题<input id="note-title" maxlength="160" placeholder="例如：停供的代价是否过于单一？" value="${esc(d.title)}" required></label><label>你的判断 / 希望改变什么<textarea id="note-body" maxlength="12000" placeholder="写下问题、期望的体验或需要一起比较的取舍…" required>${esc(d.body)}</textarea></label><button type="submit" class="primary">${offline?'保存到本机草稿':'保存讨论到项目'}</button><p>${offline?'离线讨论仅存此浏览器。请导出 JSON 后导入本地版。':'保存后写入项目讨论单。下次聊天引用讨论编号即可；不会自动修改策划或发消息。'}</p></form>`;}
function noteHTML(n){const stale=n.sourceRevision!==model.meta.revision;return `<article class="note-card"><div class="row spread"><span class="mono tiny">${esc(n.id)}</span><span class="pill">${kindLabels[n.kind]}</span></div><h3>${esc(n.title)}</h3><p>${esc(n.body)}</p><button class="source-link" data-action="target" data-id="${esc(n.target)}">${esc(name(n.target))} · ${esc(n.target)}</button>${stale?'<p class="tiny muted">来源版本已有变化；落实前请重新核对。</p>':''}<footer><select aria-label="${esc(n.id)} 状态" data-note-status="${esc(n.id)}">${Object.entries(statusLabels).map(([v,t])=>`<option value="${v}" ${n.status===v?'selected':''}>${t}</option>`).join('')}</select><button class="small" data-action="copy-note" data-id="${esc(n.id)}">复制给协作者</button></footer></article>`;}
function turnHTML(){const phases=model.phases,p=phases[state.phase];return `<div class="view-content"><div class="phase-line">${phases.map((x,i)=>`<button data-action="phase" data-value="${i}" class="${state.phase===i?'active':''}"><small>PHASE 0${i+1}</small>${x.title}</button>`).join('')}</div><div class="phase-detail"><span class="eyebrow">一轮的第 ${state.phase+1} 步</span><h2 style="margin-top:12px">${p.title}</h2><p>${p.summary}</p><ul>${p.details.map(x=>`<li>${x}</li>`).join('')}</ul><div class="tradeoff">${p.edge}</div><div class="chips">${p.nodes.map(x=>nodeButton('MECH-'+x)).join('')}</div></div><div style="margin-top:20px">${sourcesHTML(['docs/specs/system-turn-economy.md'])}</div></div>`;}
function pathsHTML(){const path=model.paths[state.path];return `<div class="view-content"><div class="path-switch">${model.paths.map((p,i)=>`<button data-action="path" data-value="${i}" class="${state.path===i?'active':''}">${esc(p.subtitle)}</button>`).join('')}</div>${notice(path.note)}<div class="journey">${path.nodes.map((id,i)=>`<div class="step"><span class="number">${i+1}</span><div class="step-body"><span class="eyebrow">${esc(id)}</span><h3>${esc(name(id))}</h3><p>${esc(path.steps[i])}</p>${nodeButton(id,'展开能力与代价')}</div></div>`).join('')}</div></div>`;}
function catalogHTML(){const t=model.tables[state.catalog];const query=state.search.toLowerCase();const rows=t.rows.filter(r=>Object.values(r).join(' ').toLowerCase().includes(query));return `<div class="view-content"><div class="catalog-layout"><nav class="catalog-menu" aria-label="内容类型">${Object.keys(model.tables).map(k=>`<button data-action="catalog" data-value="${k}" class="${state.catalog===k?'active':''}">${esc(catalogTitles[k]||k)}<span>${model.tables[k].rows.length}</span></button>`).join('')}</nav><section><div class="row spread" style="margin-bottom:16px"><input class="searchbox" id="catalog-search" type="search" placeholder="搜索当前内容…" aria-label="搜索当前内容" value="${esc(state.search)}"><span class="tiny muted">${rows.length} 条</span></div><div class="catalog-list">${rows.map(r=>`<button class="catalog-row ${state.item===key(r)?'active':''}" data-action="item" data-id="${esc(key(r))}"><div class="id">${esc(key(r))}</div><h3>${esc(r.name||r.title||r.rationale||r.on_choose||r.success_fact||key(r))}</h3><p>${esc(r.target_requirement||r.anchor_route||r.need||r.irreversible_cost||r.institution_acceptance||r.notes||r.value||Object.values(r).slice(1,3).join(' · '))}</p></button>`).join('')||'<div class="empty-search">没有匹配条目。可以换个关键词或查看其他内容类型。</div>'}</div></section></div></div>`;}
function params(name){return Object.fromEntries(model.tables[name].rows.map(r=>[r.id,Number(r.value)]));}
function calculate(){return calculatePreview(state.calc,params('run_parameters'));}
function labHTML(){const p=params('run_parameters'),w=params('civilization_parameters'),c=state.calc;const controls=[['planet','有效星球锚点',w.planet_domains*w.institutions_per_domain],['system','有效星系锚点',w.system_domains*w.institutions_per_domain],['cosmic','有效宇宙锚点',w.cosmic_domains*w.institutions_per_domain],['insight','有限洞见',p.insight_cap],['wounds','当前创伤',100]];return `<div class="view-content">${notice('这是当前公式的可解释试算：假设输入的锚点均有效且已经支付供奉。没有模拟建立条件、文明反制、时间或完整经济。')}<div class="calculator"><div class="calc-controls">${controls.map(([id,label,max])=>`<div class="slider-control"><label for="calc-${id}">${label}<strong id="value-${id}" class="mono">${c[id]}</strong></label><input id="calc-${id}" data-calc="${id}" type="range" min="0" max="${max}" value="${c[id]}"></div>`).join('')}<button data-action="calc-reset">恢复初始假设</button></div><div class="calc-result" id="calc-result"></div></div><div class="calc-secondary"><h3>供奉收入 · 一个教团</h3><p class="tiny muted">合资格信众 <input data-calc="population" type="number" min="0" max="${w.domain_population_capacity}" value="${c.population}" aria-label="合资格信众"> 凝聚 <input data-calc="cohesion" type="number" min="0" max="100" value="${c.cohesion}" aria-label="凝聚"> <span id="income-result"></span></p><p class="tiny muted" style="margin-top:12px">按守持策略计算；不包含其他收入与维护支出，不假定当轮新增人口立即产出。</p></div><div style="margin-top:20px">${sourcesHTML(['docs/specs/system-progression.md','docs/specs/system-turn-economy.md','data/run_parameters.csv'])}</div></div>`;}
function updateCalculation(){const r=calculate(),p=params('run_parameters');for(const k of ['planet','system','cosmic','insight','wounds'])if($('#value-'+k))$('#value-'+k).textContent=state.calc[k];$('#calc-result').innerHTML=`<span class="eyebrow">当前苏醒 / 终局前</span><div class="big-number">${r.a}<span style="font-size:17px;letter-spacing:0;color:var(--muted)"> / ${p.awakening_terminal}</span></div><div class="bar-track"><div style="width:${r.a}%"></div></div><div class="formula-parts"><b>${p.initial_awakening} 自我</b> + <b>${state.calc.insight} 洞见</b> + <b>${r.anchor} 锚点</b> − <b>${state.calc.wounds} 创伤</b></div><div class="row spread tiny"><span>每轮锚点维护 <b>${r.upkeep} 信仰</b></span><span>下一轮低语 <b>${r.whispers}</b></span></div><div class="notice">${r.qualified?'数值与跨层级条件满足；仍须人物、媒介、资源和持续仪式，不能视为可获胜。':'尚未满足降临的数值与跨层级条件；完整门槛见进度规则。'}</div><button class="small" data-action="discuss-calc">把这组假设带入讨论</button>`;$('#income-result').innerHTML=`→ <b>${r.income} 信仰 / 轮</b>`;}
function discussionHTML(){const filtered=feedback.items.filter(n=>state.status==='all'||n.status===state.status);return `<div class="view-content"><div class="discussion-toolbar"><div class="filters">${[['all','全部'],...Object.entries(statusLabels)].map(([id,label])=>`<button data-action="status" data-value="${id}" class="${state.status===id?'active':''}">${label}</button>`).join('')}</div><div class="row"><button class="small" data-action="import-notes">导入 JSON</button><button class="small" data-action="export-json">备份 JSON</button></div></div>${notice(offline?'离线讨论只保存在本浏览器。导出 JSON 可带回项目版，不能自动同步给协作者。':'讨论直接保存到 docs/game-state/feedback.json。讨论状态只管理沟通流程；采纳与修改仍须更新正式规则和决策记录。')}<div class="discussion-list">${filtered.length?filtered.map(noteHTML).join(''):`<div class="discussion-empty"><span class="eyebrow">A SHARED LANGUAGE</span><h2>${feedback.items.length?'这个状态下还没有议题。':'从一个具体机制开始讨论。'}</h2><p>选中节点、关系或内容条目，记录问题和期望。稳定编号、来源版本和关联规则会随讨论一起保留。</p><button data-action="view" data-view="map" class="primary">返回机制全景</button></div>`}</div><p class="discussion-help">协作方式：标注 → 复制讨论上下文给协作者 → 核对影响 → 修改权威规则与数据 → 刷新索引。<br>浏览器不会假装 AI 已收到消息，也不会直接把一条讨论改写成正式设计。</p></div>`;}
function bindGraphPan(){const box=$('.graph-viewport');let drag=null;box.addEventListener('pointerdown',e=>{if(e.target.closest('[data-action]'))return;drag={x:e.clientX,y:e.clientY,left:box.scrollLeft,top:box.scrollTop};box.setPointerCapture(e.pointerId);});box.addEventListener('pointermove',e=>{if(drag){box.scrollLeft=drag.left-e.clientX+drag.x;box.scrollTop=drag.top-e.clientY+drag.y;}});box.addEventListener('pointerup',()=>drag=null);box.addEventListener('pointercancel',()=>drag=null);}
function contextFor(id){
 const f=feature(id),r=relation(id),d=targetData(id),t=tracked(id);
 const url=new URLSearchParams({view:t?'delivery':d?'catalog':'map',target:id});if(t)url.set('group',t.group);if(d)url.set('catalog',d.table);
 const summary=f?.summary||r?.summary||t?.rule||t?.scope||t?.title||(d?.row?Object.entries(d.row).map(([k,v])=>`${fieldLabel(k,d.table)}：${displayField(k,v)}`).join('\n'):'');
 const implementation=t?'\n\n'+deliveryContext(model.delivery,t,trackingStatusLabel):'';
 return `# ${name(id)} · ${id}\n\n来源版本：${model.meta.revision}\n定位：${location.href.split('#')[0]}#${url}\n\n${summary}${implementation}\n\n权威来源：\n${sourcePaths(id).map(p=>'- '+p).join('\n')}\n\n范围：规则覆盖、任务接入与验收分别记录；当前证据不代表整款游戏完成或体验通过。`;
}
function noteText(n){return `${contextFor(n.target)}\n\n## ${n.id} · ${n.title}\n类型：${kindLabels[n.kind]}\n状态：${statusLabels[n.status]}\n记录时来源版本：${n.sourceRevision}\n\n${n.body}\n\n请先核对当前来源和关联影响，再讨论或实施；讨论记录本身不替代正式决策。\n`;}
async function copy(text){try{await navigator.clipboard.writeText(text);toast('已复制。');}catch{const area=document.createElement('textarea');area.value=text;document.body.append(area);area.select();const ok=document.execCommand('copy');area.remove();if(ok)toast('已复制。');else{showDocument('可手动复制的上下文',text);toast('浏览器限制了剪贴板，请在弹窗中手动复制。');}}}
function download(filename,text,type='text/plain;charset=utf-8'){const url=URL.createObjectURL(new Blob([text],{type}));const a=document.createElement('a');a.href=url;a.download=filename;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
function showDocument(title,text){$('#doc-title').textContent=title;$('#doc-body').textContent=text;$('#document').showModal();}
function showSource(path){if(model.documents[path])showDocument(path,model.documents[path]);else{const t=Object.values(model.tables).find(t=>t.path===path);if(t)showDocument(path,[t.columns.join(' | '),...t.rows.map(r=>t.columns.map(c=>r[c]).join(' | '))].join('\n'));else showDocument(path,'该来源的范围与说明请在项目中阅读：'+path);}}
async function saveFeedback(items){
 if(writingFeedback)throw new Error('上一笔保存仍在进行，请稍后再试。');
 validateFeedback({schemaVersion:1,revision:feedback.revision,items},targetExists);
 writingFeedback=true;
 try{
  if(offline){const next={schemaVersion:1,revision:feedback.revision+1,items};localStorage.setItem('cthulhu-workbench-offline-feedback-v1',JSON.stringify(next));feedback=next;}
  else feedback=await request('/api/feedback',{method:'POST',headers:{'Content-Type':'application/json','X-Workbench-Token':model.token},body:JSON.stringify({revision:feedback.revision,items})});
 }finally{writingFeedback=false;}
}
async function saveNote(){const form=$('#note-form');if(!form.reportValidity())return;const target=state.target,now=new Date().toISOString();const item={id:`DISC-${crypto.randomUUID().slice(0,8).toUpperCase()}`,target:state.target,title:$('#note-title').value.trim(),body:$('#note-body').value.trim(),kind:$('#note-kind').value,status:'open',createdAt:now,updatedAt:now,sourceRevision:model.meta.revision};if(!item.title||!item.body)return toast('请填写标题和具体内容。');try{await saveFeedback([...feedback.items,item]);if(drafts[target]?.title.trim()===item.title&&drafts[target]?.body.trim()===item.body)delete drafts[target];persistDraft();render();toast(`${item.id} 已${offline?'保存到本浏览器':'写入项目讨论单'}。`);}catch(e){toast(e.message);}}
document.addEventListener('click',async e=>{const b=e.target.closest('[data-action]');if(!b)return;const a=b.dataset.action;try{
 if(a==='view'){state.view=b.dataset.view;state.search='';state.detail='ability';const targets={turn:'MECH-TURN',paths:model.paths[state.path].nodes[0],catalog:'DATA-'+state.catalog+(state.item?'/'+state.item:''),lab:'MECH-AWAKENING'};if(targets[state.view])state.target=targets[state.view];hashWrite();render();window.scrollTo({top:0});}
 if(a==='target'){select(b.dataset.id);}
 if(a==='delivery-group'){state.deliveryGroup=b.dataset.value;state.deliveryStatus='all';hashWrite();render();}
 if(a==='delivery-feature'){state.view='delivery';state.deliveryGroup='requirements';state.deliveryFeature=b.dataset.id;state.deliveryStatus='all';state.deliverySearch='';hashWrite();render();$('#main-view').scrollIntoView({block:'start'});}
 if(a==='delivery-reset'){state.deliveryFeature='all';state.deliveryStatus='all';state.deliverySearch='';hashWrite();render();}
 if(a==='edge'){state.focus=true;select(b.dataset.id);}
 if(a==='detail'){state.detail=b.dataset.value;render();if(state.detail==='notes')$('#note-title')?.focus();}
 if(a==='lens'){state.lens=b.dataset.value;render();}
 if(a==='focus'){state.focus=!state.focus;render();}
 if(a==='back-main')$('#main-view').scrollIntoView({block:'start'});
 if(a==='wide-map'){state.graphWide=!state.graphWide;state.fit=true;render();}
 if(a==='fit-map'){state.fit=true;state.zoom=$('.graph-viewport').clientWidth/1120;$('#graph-scale').style.width=state.zoom*1120+'px';}
 if(a==='zoom'){state.fit=false;state.zoom=Math.max(.35,Math.min(1.8,state.zoom+Number(b.dataset.value)*.15));$('#graph-scale').style.width=state.zoom*1120+'px';}
 if(a==='reset-map'){state.target='';state.zoom=1;state.fit=true;state.focus=false;state.search='';state.lens='全部';hashWrite();render();}
 if(a==='path'){state.path=Number(b.dataset.value);state.view='paths';state.target=model.paths[state.path].nodes[0];hashWrite();render();window.scrollTo({top:0});}
 if(a==='phase'){state.phase=Number(b.dataset.value);render();}
 if(a==='catalog'){state.catalog=b.dataset.value;state.item='';state.target='DATA-'+state.catalog;state.search='';state.detail='ability';hashWrite();render();}
 if(a==='item'){state.item=b.dataset.id;select('DATA-'+state.catalog+'/'+state.item);}
 if(a==='status'){state.status=b.dataset.value;render();}
 if(a==='copy-link'){hashWrite();await copy(location.href);}
 if(a==='copy-context')await copy(contextFor(state.target));
 if(a==='copy-note')await copy(noteText(feedback.items.find(n=>n.id===b.dataset.id)));
 if(a==='source')showSource(b.dataset.path);
 if(a==='provenance')showDocument('来源版本与复核状态',`模式：${offline?'离线快照（不会自动读取项目变化）':'本地项目（打开或手动刷新时读取）'}\n来源版本：${model.meta.revision}\n读取 / 生成时间：${model.meta.loadedAt}\n最近语义复核基线：${model.meta.baselineAt||'尚未建立'}\n登记来源：${model.meta.sourceCount} 份\n\n待复核：\n${[...model.meta.changed,...model.meta.unowned].join('\n')||'读取时未发现文件漂移。文件一致不等于玩法验证通过。'}\n\n原始规则、数据与摘要分别维护。更新来源按钮不自动确认摘要。`);
 if(a==='close-doc')$('#document').close();
 if(a==='constraints')showDocument('作者已确认的方向',model.atlas.constraints.map(c=>`${c.id}\n${c.statement}\n来源：${c.source.path}\n`).join('\n'));
 if(a==='calc-reset'){state.calc={planet:1,system:1,cosmic:1,insight:0,wounds:0,population:81,cohesion:80};render();}
 if(a==='discuss-calc'){const r=calculate(),c=state.calc;state.target='MECH-AWAKENING';state.detail='notes';drafts[state.target]={kind:'question',title:'讨论这组锚点与苏醒假设',body:`公式试算（不是完整游戏模拟）：星球锚点 ${c.planet}、星系锚点 ${c.system}、宇宙锚点 ${c.cosmic}；洞见 ${c.insight}，创伤 ${c.wounds}。\n计算：当前苏醒 ${r.a}，每轮锚点维护 ${r.upkeep} 信仰，下一轮低语 ${r.whispers}。\n\n我的问题 / 期望：`};persistDraft();hashWrite();render();$('#note-body')?.focus();}
 if(a==='export-notes')download('邪神苏醒-讨论单.md',feedback.items.length?feedback.items.map(noteText).join('\n---\n\n'):'# 讨论单\n\n当前没有讨论记录。\n');
 if(a==='export-json')download('cthulhu-discussions.json',JSON.stringify(feedback,null,2),'application/json');
 if(a==='import-notes')$('#import-file').click();
 if(a==='refresh'){if(offline)return toast('这是离线快照；重新生成后打开，或使用项目本地版。');model=await request('/api/model');feedback=await request('/api/feedback');render();toast(model.meta.changed.length?'已读取最新原文和数据；索引摘要需要复核。':'已读取最新项目来源与讨论。');}
 }catch(error){toast(error.message);}});
document.addEventListener('keydown',e=>{if((e.key==='Enter'||e.key===' ')&&e.target.matches('g[role=button],path[role=button]')){e.preventDefault();e.target.dispatchEvent(new MouseEvent('click',{bubbles:true}));}if(e.key==='Escape')$('#document').close();});
document.addEventListener('submit',e=>{if(e.target.id==='note-form'){e.preventDefault();saveNote();}});
document.addEventListener('input',e=>{
 if(['note-title','note-body','note-kind'].includes(e.target.id)){drafts[state.target]={title:$('#note-title').value,body:$('#note-body').value,kind:$('#note-kind').value};persistDraft();}
 if(e.target.id==='delivery-search'){const pos=e.target.selectionStart;state.deliverySearch=e.target.value;hashWrite();render();const input=$('#delivery-search');input.focus();input.setSelectionRange(pos,pos);}
 if(e.target.id==='mechanism-search'||e.target.id==='catalog-search'){const id=e.target.id,pos=e.target.selectionStart;state.search=e.target.value;render();const input=$('#'+id);input.focus();if(input.type==='search')input.setSelectionRange(pos,pos);}
 if(e.target.dataset.calc){let n=Number(e.target.value);if(!Number.isFinite(n))n=0;n=Math.max(Number(e.target.min),Math.min(Number(e.target.max),n));state.calc[e.target.dataset.calc]=Math.floor(n);updateCalculation();}
});
document.addEventListener('change',async e=>{if(e.target.id==='delivery-feature-filter'){state.deliveryFeature=e.target.value;hashWrite();render();}if(e.target.id==='delivery-status-filter'){state.deliveryStatus=e.target.value;hashWrite();render();}if(e.target.dataset.calc)e.target.value=state.calc[e.target.dataset.calc];if(e.target.dataset.noteStatus){const id=e.target.dataset.noteStatus,old=feedback;try{await saveFeedback(feedback.items.map(n=>n.id===id?{...n,status:e.target.value,updatedAt:new Date().toISOString()}:n));render();toast('讨论状态已保存；正式设计没有被自动更改。');}catch(error){feedback=old;render();toast(error.message);}}});
$('#import-file').addEventListener('change',async e=>{try{const file=e.target.files[0];if(!file)return;if(file.size>2_000_000)throw new Error('文件过大。');const incoming=validateFeedback(JSON.parse(await file.text()),targetExists);const merged=mergeFeedback(feedback.items,incoming.items);const added=merged.length-feedback.items.length;await saveFeedback(merged);render();toast(`已合并 ${added} 条讨论；原记录保留。`);}catch(error){toast(error.message);}finally{e.target.value='';}});
window.addEventListener('hashchange',()=>{hashRead();render();});
try{model=offline?window.WORKBENCH_SNAPSHOT:await request('/api/model');feedback=offline?safeRead('cthulhu-workbench-offline-feedback-v1',{schemaVersion:1,revision:0,items:[]}):await request('/api/feedback');validateFeedback(feedback,targetExists);hashRead();render();}catch(error){$('#app').innerHTML=`<div class="loading"><h1>工作台暂时无法读取来源</h1><p style="margin-top:15px">${esc(error.message)}</p><p class="muted" style="margin-top:10px">请确认本地服务正在运行，或使用重新生成的离线快照。</p></div>`;}
